def load_json(path: Path) -> Tuple[Optional[Any], List[str]]:
    """Load UTF-8 JSON and return all file-level errors without raising."""
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        return None, [f"无法读取 JSON 文件 {path}: {exc}"]
    try:
        return json.loads(text), []
    except json.JSONDecodeError as exc:
        return None, [f"JSON 解析失败（第 {exc.lineno} 行第 {exc.colno} 列）: {exc.msg}"]


def _is_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _voice_kind(speaker: str, mode: str) -> str:
    upper = mode.upper()
    if "OS" in upper or "内心" in mode:
        return "os"
    if "VO" in upper:
        return "vo"
    if speaker in {"系统声", "机械的电子音女声", "广播声", "电话声", "录音声"}:
        return "system"
    if speaker in {"解说", "旁白", "OV"} or "旁白" in mode:
        return "narration"
    if "画外音" in mode:
        return "vo"
    return "dialogue"


def _storyboard_voice_groups(
    data: Mapping[str, Any],
) -> List[List[VoiceRecord]]:
    groups: List[List[VoiceRecord]] = []
    storyboards = data.get("storyboard")
    if not isinstance(storyboards, list):
        return groups
    for storyboard in storyboards:
        voices: List[VoiceRecord] = []
        prompt = storyboard.get("prompt") if isinstance(storyboard, dict) else None
        if isinstance(prompt, str):
            for shot_index, line in enumerate(prompt.splitlines()[1:]):
                for match in VOICE_RE.finditer(line):
                    speaker = match.group("named") or match.group("anonymous") or ""
                    mode = match.group("named_mode") or match.group("anonymous_mode") or ""
                    if speaker == "OV":
                        speaker = "旁白"
                    voices.append(
                        (
                            shot_index,
                            speaker,
                            _voice_kind(speaker, mode),
                            semantic_chars(match.group("body")),
                            mode,
                        )
                    )
        groups.append(voices)
    return groups


def calculate_content_duration(
    voice_target_secs: Sequence[float],
    shot_count: int,
    pause_after_secs: Optional[Sequence[float]] = None,
) -> int:
    """Accumulate the continuous voice clock before one final whole-second round-up."""
    del shot_count  # visual beats run in parallel with the continuous narration track
    pauses = pause_after_secs or [0] * len(voice_target_secs)
    content_seconds = sum(float(value) for value in voice_target_secs)
    content_seconds += sum(float(value) for value in pauses)
    return max(4, math.ceil(content_seconds + 1 - 1e-9))


def _validate_voice_ledger(
    data: Mapping[str, Any],
    narration_plan: Any,
    source_text: Optional[str],
    errors: List[str],
) -> Optional[
    Tuple[
        List[List[Mapping[str, Any]]],
        List[List[Tuple[Mapping[str, Any], int]]],
    ]
]:
    plan_errors = validate_narration_plan(narration_plan, source_text)
    errors.extend(f"narration_plan: {error}" for error in plan_errors)
    if plan_errors or not isinstance(narration_plan, dict):
        return None
    units = narration_plan.get("narrationUnits")
    if not isinstance(units, list):
        return None
    expected_units = [unit for unit in units if isinstance(unit, dict)]
    actual_groups = _storyboard_voice_groups(data)
    actual = [
        (storyboard_index, shot_index, speaker, mode, body, raw_mode)
        for storyboard_index, voices in enumerate(actual_groups)
        for shot_index, speaker, mode, body, raw_mode in voices
    ]
    mapped_units: List[List[Mapping[str, Any]]] = [
        [] for _ in actual_groups
    ]
    mapped_unit_shots: List[List[Tuple[Mapping[str, Any], int]]] = [
        [] for _ in actual_groups
    ]
    actual_index = 0
    for unit_index, unit in enumerate(expected_units, start=1):
        expected_speaker = unit["speaker"]
        expected_mode = unit["mode"]
        expected_text = semantic_chars(unit["text"])
        if actual_index >= len(actual):
            errors.append(f"语音账本未完整覆盖：N{unit_index:03d} 未出现在分镜中")
            return None
        (
            storyboard_index,
            shot_index,
            actual_speaker,
            actual_mode,
            actual_text,
            _actual_raw_mode,
        ) = actual[actual_index]
        if actual_speaker != expected_speaker or actual_mode != expected_mode:
            errors.append(
                f"语音说话人或模式不一致：N{unit_index:03d} 应为 "
                f"{expected_speaker}/{expected_mode}，实际为 {actual_speaker}/{actual_mode}"
            )
            return None
        if actual_text != expected_text:
            if expected_text.startswith(actual_text):
                errors.append(
                    f"N{unit_index:03d} 每条语音单元必须对应一段完整引号语音；"
                    "请在 narration_plan 阶段先拆成多个自然意群"
                )
            else:
                errors.append(f"语音正文与计划不一致：N{unit_index:03d} 被改写、增删或换序")
            return None
        if unit.get("hookRole") == "primary" and (storyboard_index, shot_index) != (0, 0):
            errors.append("前三秒主钩子 N001 必须从 storyboard[0] 镜头1 开始声画同步")
            return None
        mapped_units[storyboard_index].append(unit)
        mapped_unit_shots[storyboard_index].append((unit, shot_index))
        actual_index += 1
    if actual_index < len(actual):
        errors.append("输出包含 narration_plan 不存在的新增语音")
        return None
    return mapped_units, mapped_unit_shots


def _validate_content_durations(
    storyboards: Sequence[Any],
    parsed_storyboards: Sequence[Sequence[str]],
    mapped_units: Sequence[Sequence[Mapping[str, Any]]],
    duration_sec: int,
    errors: List[str],
) -> None:
    for index, storyboard in enumerate(storyboards):
        if not isinstance(storyboard, dict) or index >= len(parsed_storyboards):
            continue
        shot_count = len(parsed_storyboards[index])
        if shot_count == 0:
            continue
        units = mapped_units[index] if index < len(mapped_units) else []
        voice_target_secs: List[float] = [
            unit.get("targetSec", 0)
            for unit in units
            if isinstance(unit.get("targetSec"), (int, float))
        ]
        pause_after_secs: List[float] = [
            float(unit.get("pauseAfterSec", 0))
            for unit in units
            if isinstance(unit.get("targetSec"), (int, float))
        ]
        _validate_one_content_duration(
            index,
            storyboard,
            shot_count,
            voice_target_secs,
            pause_after_secs,
            duration_sec,
            errors,
        )


def _validate_one_content_duration(
    index: int,
    storyboard: Mapping[str, Any],
    shot_count: int,
    voice_target_secs: Sequence[float],
    pause_after_secs: Sequence[float],
    duration_sec: int,
    errors: List[str],
) -> None:
    speech_sec = sum(voice_target_secs)
    pause_sec = sum(pause_after_secs)
    expected = calculate_content_duration(voice_target_secs, shot_count, pause_after_secs)
    breakdown = (
        f"连续语音 {speech_sec:g} 秒，剧情停顿 {pause_sec:g} 秒，安全头尾 1 秒；"
        "画面镜头与语音并行，不按镜头数重复加时"
    )
    if expected > duration_sec:
        errors.append(
            f"storyboard[{index}] 内容计算时长 {expected} 秒超过上限 {duration_sec} 秒，"
            f"必须拆分；{breakdown}"
        )
        return
    actual_duration = storyboard.get("duration")
    if _is_int(actual_duration) and actual_duration != expected:
        errors.append(
            f"storyboard[{index}].duration 应按内容计算为 {expected} 秒，"
            f"实际为 {actual_duration} 秒；{breakdown}"
        )


def _validate_prompt_content_durations(
    storyboards: Sequence[Any],
    parsed_storyboards: Sequence[Sequence[str]],
    duration_sec: int,
    errors: List[str],
) -> None:
    actual_voice_groups = _storyboard_voice_groups({"storyboard": storyboards})
    for index, storyboard in enumerate(storyboards):
        if not isinstance(storyboard, dict) or index >= len(parsed_storyboards):
            continue
        shot_count = len(parsed_storyboards[index])
        if shot_count == 0:
            continue
        voices = actual_voice_groups[index] if index < len(actual_voice_groups) else []
        voice_target_secs = [
            expected_target_sec(body, DEFAULT_PLAYBACK_RATE, mode)
            for _, _, mode, body, _raw_mode in voices
        ]
        _validate_one_content_duration(
            index,
            storyboard,
            shot_count,
            voice_target_secs,
            [0] * len(voice_target_secs),
            duration_sec,
            errors,
        )


def _logical_scene_name(name: str) -> str:
    if name.startswith(SPACE_MASTER_PREFIX):
        return name[len(SPACE_MASTER_PREFIX) :]
    return name


def _validate_plan_scene_alignment(
    mapped_unit_shots: Sequence[Sequence[Tuple[Mapping[str, Any], int]]],
    parsed_storyboards: Sequence[Sequence[str]],
    errors: List[str],
) -> None:
    for storyboard_index, pairs in enumerate(mapped_unit_shots):
        lines = (
            parsed_storyboards[storyboard_index]
            if storyboard_index < len(parsed_storyboards)
            else []
        )
        for unit, shot_index in pairs:
            planned_scene = str(unit.get("scene", "")).split("｜", 1)[0].strip()
            line = lines[shot_index] if shot_index < len(lines) else ""
            actual_scenes = {
                _logical_scene_name(name)
                for token_type, name in TOKEN_RE.findall(line)
                if token_type == "场景"
            }
            if not any(
                actual_scene == planned_scene
                or actual_scene.startswith(f"{planned_scene}（")
                for actual_scene in actual_scenes
            ):
                errors.append(
                    f"storyboard[{storyboard_index}] 镜头{shot_index + 1} 的语音"
                    f"未使用计划场景“{planned_scene}”，实际场景为 {sorted(actual_scenes)}"
                )


def _validate_assets(data: Mapping[str, Any], errors: List[str]) -> Dict[str, Set[str]]:
    declared: Dict[str, Set[str]] = {field: set() for field in ASSET_LABELS}
    for field, label in ASSET_LABELS.items():
        assets = data.get(field)
        if not isinstance(assets, list):
            errors.append(f"顶层 {field} 必须是数组")
            continue
        for index, asset in enumerate(assets):
            location = f"{field}[{index}]"
            if not isinstance(asset, dict):
                errors.append(f"{location} 必须是对象")
                continue
            if list(asset.keys()) != ASSET_FIELDS:
                errors.append(f"{location} 字段顺序必须为 {', '.join(ASSET_FIELDS)}")
            name = asset.get("name")
            prompt = asset.get("prompt")
            if not isinstance(name, str) or not name.strip():
                errors.append(f"{location}.name 必须是非空字符串")
            elif name in declared[field]:
                errors.append(f"{label}资产名称重复: {name}")
            else:
                declared[field].add(name)
                if field == "character" and name in NON_VISUAL_VOICE_ASSETS:
                    errors.append(f"{location} 匿名声音“{name}”不得声明为角色资产")
            if not isinstance(prompt, str) or not prompt.strip():
                errors.append(f"{location}.prompt 必须是非空字符串")
    return declared


def _validate_scene_masters(
    data: Mapping[str, Any],
    declared: Mapping[str, Set[str]],
    errors: List[str],
) -> Tuple[Dict[str, str], Dict[str, Set[str]]]:
    """Validate scene assets named 空间母版-X and collect their dependency tokens."""
    masters: Dict[str, str] = {}
    used: Dict[str, Set[str]] = {field: set() for field in ASSET_LABELS}
    scenes = data.get("scene")
    if not isinstance(scenes, list):
        return masters, used
    for index, asset in enumerate(scenes):
        if not isinstance(asset, dict):
            continue
        name, prompt = asset.get("name"), asset.get("prompt")
        if not isinstance(name, str) or not name.startswith(SPACE_MASTER_PREFIX):
            continue
        base = name[len(SPACE_MASTER_PREFIX) :].strip()
        if not base:
            errors.append(f"scene[{index}] 空间母版名称必须在前缀后包含基础场景名")
            continue
        if base in masters:
            errors.append(f"基础场景“{base}”只能声明一个无状态后缀的空间母版")
        masters[base] = name
        if base not in declared["scene"]:
            errors.append(f"空间母版“{name}”缺少基础场景资产“{base}”")
        scene_dependencies: Set[str] = set()
        if isinstance(prompt, str):
            for token_type, token_name in TOKEN_RE.findall(prompt):
                field = TOKEN_TO_FIELD[token_type]
                used[field].add(token_name)
                if token_name not in declared[field]:
                    errors.append(
                        f"scene[{index}] 空间母版 prompt 的{ASSET_LABELS[field]}引用“{token_name}”"
                        "未在顶层资产中声明"
                    )
                if field == "scene":
                    scene_dependencies.add(token_name)
        if base not in scene_dependencies:
            errors.append(f"空间母版“{name}”的 prompt 必须引用 @[场景-{base}] 作为空间基底")
    return masters, used


def _validate_reference_array(
    shot: Mapping[str, Any],
    field: str,
    index: int,
    declared: Mapping[str, Set[str]],
    errors: List[str],
) -> Optional[Set[str]]:
    values = shot.get(field)
    if not isinstance(values, list):
        errors.append(f"storyboard[{index}].{field} 必须是数组")
        return None
    if any(not isinstance(value, str) or not value for value in values):
        errors.append(f"storyboard[{index}].{field} 只能包含非空字符串")
        return None
    value_set = set(values)
    if len(value_set) != len(values):
        errors.append(f"storyboard[{index}].{field} 不得包含重复名称")
    label = ASSET_LABELS[field]
    for value in values:
        if value not in declared[field]:
            errors.append(f"storyboard[{index}] {label}引用“{value}”未在顶层资产中声明")
    return value_set


def _validate_no_internal_syntax(prompt: str, index: int, errors: List[str]) -> None:
    for pattern, label in FORBIDDEN_INTERNAL_PATTERNS:
        if pattern.search(prompt):
            errors.append(f"storyboard[{index}].prompt 不得包含{label}，应编译为 Seedance 镜头N 格式")

    instruction_text = QUOTED_SPEECH_RE.sub("“”", prompt)
    if VOICE_RATE_RE.search(instruction_text):
        errors.append(
            f"storyboard[{index}].prompt 不得把数值倍速写入 Seedance 提示词；"
            "playbackRate 只用于时长规划，成片使用定性的原生快速解说指令"
        )
    for pattern, label in FORBIDDEN_VAGUE_MODEL_PATTERNS:
        if pattern.search(instruction_text):
            errors.append(
                f"storyboard[{index}].prompt 不得包含{label}，"
                "请改写为物理动作、光源、触发和可见结果"
            )

    if any(pattern.search(instruction_text) for pattern in FORBIDDEN_NEGATIVE_SLOP_PATTERNS):
        errors.append(
            f"storyboard[{index}].prompt 不得包含普通负面缺陷词或独立负面提示词清单，"
            "请改写为正向状态锁或针对当前动作顺序的短局部约束"
        )


def _parse_shot_lines(prompt: str, index: int, errors: List[str]) -> List[str]:
    lines = prompt.splitlines()
    if not lines or lines[0] != STYLE_LINE:
        errors.append(f"storyboard[{index}].prompt 首行必须是固定风格串")
    shot_lines = lines[1:] if lines else []
    if not shot_lines:
        errors.append(f"storyboard[{index}].prompt 至少需要一个镜头N 子镜头")
        return []

    actual_numbers: List[int] = []
    for line_number, line in enumerate(shot_lines, start=2):
        match = SHOT_LINE_RE.match(line)
        if match is None:
            errors.append(f"storyboard[{index}].prompt 第 {line_number} 行必须以镜头N：开头")
        else:
            actual_numbers.append(int(match.group("number")))
    expected_numbers = list(range(1, len(shot_lines) + 1))
    if len(actual_numbers) != len(shot_lines) or actual_numbers != expected_numbers:
        errors.append(f"storyboard[{index}] 镜头编号必须从镜头1连续递增")
    return shot_lines


def _validate_camera_physics(
    location: str,
    line: str,
    header: re.Match[str],
    errors: List[str],
) -> Optional[str]:
    camera_spec = header.group("camera")
    move_matches = CAMERA_MOVE_RE.findall(camera_spec)
    if len(move_matches) != 1:
        errors.append(
            f"{location} 镜头头部必须且只能使用一种标准主运镜: {', '.join(CAMERA_MOVES)}"
        )
        return None

    move = move_matches[0]
    start_scale = header.group("start")
    destinations = DEST_SCALE_RE.findall(camera_spec)

    if move in {"推镜", "拉镜"}:
        if len(destinations) != 1:
            errors.append(f"{location} {move}必须在镜头头部写明唯一“至结束景别”")
        else:
            end_scale = destinations[0]
            delta = SHOT_SCALE_INDEX[end_scale] - SHOT_SCALE_INDEX[start_scale]
            if abs(delta) > 2:
                errors.append(f"{location} 单镜景别变化不得超过两级")
            if move == "推镜" and delta <= 0:
                errors.append(f"{location} 推镜必须由松景别进入紧景别")
            if move == "拉镜" and delta >= 0:
                errors.append(f"{location} 拉镜必须由紧景别退出到松景别")
    elif destinations:
        errors.append(f"{location} {move}应保持同级景别，不得写“至结束景别”")

    if move != "固定机位":
        if MOVING_START_RE.search(line) is None:
            errors.append(f"{location} 移动镜必须写明稳定的起始构图")
        if MOVING_TRIGGER_RE.search(line) is None:
            errors.append(f"{location} 移动镜必须由可见剧情动作触发")
        if MOVING_END_RE.search(line) is None:
            errors.append(f"{location} 移动镜必须写明停稳的构图终点")
    return move


def _validate_model_shots(
    shot_lines: Sequence[str], index: int, errors: List[str]
) -> List[ShotProfile]:
    moves: List[Optional[str]] = []
    profiles: List[ShotProfile] = []
    narration_count = 0
    for line_index, line in enumerate(shot_lines, start=1):
        location = f"storyboard[{index}] 镜头{line_index}"
        header = SHOT_HEADER_RE.match(line)
        if header is None:
            errors.append(
                f"{location} 必须使用“镜头N：景别，机位，标准主运镜。”头部"
            )
            moves.append(None)
            profiles.append((None, None, None, None))
            continue
        body = line[header.end() :]
        if "画面中" not in body:
            errors.append(
                f"{location} 必须在摄影机头部后使用“画面中”写出可见画面描述，"
                "不能只写主体动作"
            )
        if SCENE_TOKEN_RE.search(body) is None:
            errors.append(
                f"{location} 必须在本镜画面描述中写出 @[场景-名称] token 和具体可见区域"
            )
        chinese_quote_depth = 0
        chinese_quotes_valid = True
        for char in line:
            if char == "“":
                chinese_quote_depth += 1
            elif char == "”":
                chinese_quote_depth -= 1
                if chinese_quote_depth < 0:
                    chinese_quotes_valid = False
                    break
        if chinese_quote_depth != 0 or not chinese_quotes_valid or line.count('"') % 2:
            errors.append(f"{location} 有文本语音的引号必须成对闭合")
        voice_matches = list(VOICE_RE.finditer(line))
        quote_matches = list(QUOTED_SPEECH_RE.finditer(line))
        if len(voice_matches) > 1:
            errors.append(f"{location} 最多只能包含一段有文本语音")
        for quote in quote_matches:
            if not any(
                voice.start() <= quote.start() and quote.end() <= voice.end()
                for voice in voice_matches
            ):
                errors.append(f"{location} 引号文本必须绑定明确说话人和声音模式")
        for voice in voice_matches:
            speaker = voice.group("named") or voice.group("anonymous") or ""
            mode = voice.group("named_mode") or voice.group("anonymous_mode") or ""
            voice_kind = _voice_kind(speaker, mode)
            if speaker in {"解说", "旁白", "OV"} and "画外音" not in mode:
                errors.append(f"{location} 匿名解说必须标明（画外音）")
            if voice_kind == "narration":
                has_native_fast_cue = all(
                    part in mode for part in NATIVE_FAST_CUE_PARTS
                )
                if narration_count == 0 and not has_native_fast_cue:
                    errors.append(
                        f"{location} 本段首个解说必须使用“画外音，"
                        "电影解说式快速清晰、连续无拖腔”的原生快讲指令"
                    )
                elif narration_count > 0 and has_native_fast_cue:
                    errors.append(
                        f"{location} 原生快讲指令只写在本段首个解说，"
                        "后续解说使用简洁的（画外音）连续承接"
                    )
                narration_count += 1
            if voice.group("named") and voice_kind == "dialogue" and not mode:
                errors.append(f"{location} 角色对白必须保留或补充简短语气括注")
            if not SPEECH_END_RE.search(voice.group("body").strip()):
                errors.append(f"{location} 有文本语音必须以完整话语标点结束")
        move = _validate_camera_physics(location, line, header, errors)
        moves.append(move)
        destinations = DEST_SCALE_RE.findall(header.group("camera"))
        end_scale = destinations[0] if len(destinations) == 1 else None
        profiles.append((header.group("start"), end_scale, header.group("angle"), move))

        if line_index == 1 and LIGHT_SOURCE_RE.search(body) is None:
            errors.append(
                f"{location} 必须写明可解释的主光来源，不能只写高对比或轮廓光"
            )

    if len(shot_lines) >= 2 and "固定机位" not in moves:
        errors.append(f"storyboard[{index}] 含两镜以上时至少需要一个固定机位稳定画面")
    if moves.count("推镜") > 1:
        errors.append(f"storyboard[{index}] 每个分镜最多使用一次推镜")
    if shot_lines and "保持半秒" not in shot_lines[-1]:
        errors.append(f"storyboard[{index}] 末镜必须写明“保持半秒”安全尾帧")
    return profiles


def _validate_native_fast_recap_density(
    storyboards: Sequence[Any], errors: List[str]
) -> None:
    """Keep long native-audio clips dense enough to read as fast recaps."""
    voice_groups = _storyboard_voice_groups({"storyboard": storyboards})
    for index, storyboard in enumerate(storyboards):
        if not isinstance(storyboard, dict):
            continue
        duration = storyboard.get("duration")
        voices = voice_groups[index] if index < len(voice_groups) else []
        if (
            not _is_int(duration)
            or duration < LONG_FAST_RECAP_MIN_DURATION
            or not any(mode == "narration" for _, _, mode, _, _ in voices)
        ):
            continue
        spoken_chars = sum(len(body) for _, _, _, body, _ in voices)
        if not (
            LONG_FAST_RECAP_MIN_SPOKEN_CHARS
            <= spoken_chars
            <= LONG_FAST_RECAP_MAX_SPOKEN_CHARS
        ):
            errors.append(
                f"storyboard[{index}] {duration} 秒原生快速解说段应集中 "
                f"{LONG_FAST_RECAP_MIN_SPOKEN_CHARS}～"
                f"{LONG_FAST_RECAP_MAX_SPOKEN_CHARS} 个有声语义字符，"
                f"实际为 {spoken_chars}；请调整语音装载或按自然边界拆分"
            )


def _unit_scene(unit: Mapping[str, Any]) -> str:
    return str(unit.get("scene", "")).split("｜", 1)[0].strip()


def _validate_storyboard_packing(
    storyboards: Sequence[Any],
    mapped_units: Sequence[Sequence[Mapping[str, Any]]],
    duration_sec: int,
    errors: List[str],
) -> None:
    """Reject avoidable short clips while preserving real scene or result boundaries."""
    if duration_sec < LONG_FAST_RECAP_MIN_DURATION:
        return
    for index in range(min(len(storyboards), len(mapped_units)) - 1):
        storyboard = storyboards[index]
        if not isinstance(storyboard, dict):
            continue
        duration = storyboard.get("duration")
        current_units = list(mapped_units[index])
        next_units = list(mapped_units[index + 1])
        if (
            not _is_int(duration)
            or duration >= LONG_FAST_RECAP_MIN_DURATION
            or not current_units
            or not next_units
        ):
            continue
        current_last = current_units[-1]
        next_first = next_units[0]
        if float(current_last.get("pauseAfterSec", 0) or 0) > 0:
            continue
        if _unit_scene(current_last) != _unit_scene(next_first):
            continue
        candidate_units = [*current_units, next_first]
        candidate_targets = [float(unit.get("targetSec", 0) or 0) for unit in candidate_units]
        candidate_pauses = [
            float(unit.get("pauseAfterSec", 0) or 0) for unit in candidate_units
        ]
        candidate_duration = calculate_content_duration(
            candidate_targets, 0, candidate_pauses
        )
        candidate_chars = sum(
            len(semantic_chars(str(unit.get("text", "")))) for unit in candidate_units
        )
        has_narration = any(unit.get("mode") == "narration" for unit in candidate_units)
        if (
            has_narration
            and candidate_duration <= duration_sec
            and candidate_chars <= LONG_FAST_RECAP_MAX_SPOKEN_CHARS
        ):
            errors.append(
                f"storyboard[{index}] 只有 {duration} 秒且下一语音单元仍可在同场装入；"
                "应让连续解说继续装载到 12～15 秒附近，或在真实反转、"
                "重大结果、时空切换处设置 0.5 秒停顿后再切分"
            )


def _validate_visual_beat_density(
    index: int, duration: int, shot_count: int, errors: List[str]
) -> None:
    """Keep recap visuals readable: one visible beat generally lasts 2–3 seconds."""
    minimum = max(1, math.ceil(duration / 3))
    maximum = max(minimum, math.floor(duration / 2))
    if not minimum <= shot_count <= maximum:
        errors.append(
            f"storyboard[{index}] {duration} 秒应安排 {minimum}..{maximum} 个"
            f"2～3 秒视觉镜头，实际为 {shot_count} 个"
        )


def validate_directing_arc(
    storyboard_profiles: Sequence[Sequence[ShotProfile]],
) -> List[str]:
    """Reject long sequences whose scale or camera plan has collapsed."""
    errors: List[str] = []
    valid_by_storyboard = [
        [
            (start_scale, end_scale, angle, move)
            for start_scale, end_scale, angle, move in profiles
            if start_scale and angle and move
        ]
        for profiles in storyboard_profiles
    ]

    for index, profiles in enumerate(valid_by_storyboard):
        scales = [
            scale
            for start_scale, end_scale, _, _ in profiles
            for scale in (start_scale, end_scale)
            if scale
        ]
        if len(profiles) >= 4 and len(set(scales)) < 2:
            errors.append(
                f"storyboard[{index}] 景别塌缩：四镜以上不得全部使用同一景别；"
                "按空间建立、关系动作、证据细节或反应落点分配景别"
            )

    flattened = [profile for profiles in valid_by_storyboard for profile in profiles]
    if len(flattened) < 8:
        return errors

    scales = [
        scale
        for start_scale, end_scale, _, _ in flattened
        for scale in (start_scale, end_scale)
        if scale
    ]
    angles = [angle for _, _, angle, _ in flattened]
    moves = [move for _, _, _, move in flattened]
    if not any(scale in {"远景", "全景", "中远景"} for scale in scales):
        errors.append("全片导演弧线缺少远景/全景/中远景空间建立镜")
    if not any(scale in {"特写", "大特写"} for scale in scales):
        errors.append("全片导演弧线缺少特写/大特写证据或落点镜")

    moving = [move for move in moves if move != "固定机位"]
    if not moving and len(set(scales)) < 4 and len(set(angles)) < 2:
        errors.append(
            "全片摄影方案塌缩为固定机位、有限景别和单一机位："
            "若采用有意静止声部，必须用明确的景别覆盖或机位变化建立导演弧线"
        )
    if (
        len(flattened) >= 24
        and len(moving) >= 4
        and len(moving) * 3 >= len(flattened)
        and len(set(moving)) < 2
    ):
        errors.append("长序列同一种移动镜覆盖三分之一以上镜头，必须重新分配运动动机")
    return errors


def _collect_natural_points(
    lines: Sequence[str], pattern: re.Pattern[str]
) -> List[Tuple[int, str]]:
    points: List[Tuple[int, str]] = []
    for line_index, line in enumerate(lines):
        for match in pattern.finditer(line):
            points.append((line_index, match.group("type")))
    return points


def _validate_storyboard_bridges(
    storyboards: Sequence[Sequence[str]], errors: List[str]
) -> None:
    total = len(storyboards)
    incoming: List[Optional[str]] = [None] * total
    outgoing: List[Optional[str]] = [None] * total

    for index, lines in enumerate(storyboards):
        if not lines:
            continue
        in_points = _collect_natural_points(lines, IN_POINT_RE)
        out_points = _collect_natural_points(lines, OUT_POINT_RE)
        raw_in_count = sum(line.count("开头承接") for line in lines)
        raw_out_count = sum(line.count("结尾供") for line in lines)

        if raw_in_count != len(in_points):
            errors.append(f"storyboard[{index}] 入点类型无效；只允许规定的六类自然语言切点")
        if raw_out_count != len(out_points):
            errors.append(f"storyboard[{index}] 出点类型无效；只允许规定的六类自然语言切点")

        if index == 0:
            if in_points:
                errors.append("storyboard[0] 首个分镜不得包含“开头承接”")
        elif len(in_points) != 1 or in_points[0][0] != 0:
            errors.append(f"storyboard[{index}] 只允许在首个镜头放一个自然语言入点")
        else:
            incoming[index] = in_points[0][1]

        if index == total - 1:
            if out_points:
                errors.append(f"storyboard[{index}] 末个分镜不得包含“结尾供”")
        elif len(out_points) != 1 or out_points[0][0] != len(lines) - 1:
            errors.append(f"storyboard[{index}] 只允许在末个镜头放一个自然语言出点")
        else:
            outgoing[index] = out_points[0][1]

    for index in range(total - 1):
        if outgoing[index] is not None and incoming[index + 1] is not None:
            if outgoing[index] != incoming[index + 1]:
                errors.append(
                    f"storyboard[{index}] 出点与 storyboard[{index + 1}] 入点类型不闭环"
                )


def validate_storyboard(
    data: Any,
    duration_sec: int,
    narration_plan: Any = None,
    source_text: Optional[str] = None,
) -> List[str]:
    """Return every structural validation error found in a storyboard document."""
    errors: List[str] = []
    if not _is_int(duration_sec) or duration_sec < 4:
        return ["duration_sec 必须是大于等于 4 的整数"]
    if not isinstance(data, dict):
        return ["JSON 顶层必须是对象"]
    if list(data.keys()) != TOP_LEVEL_FIELDS:
        errors.append(f"顶层字段顺序必须为 {', '.join(TOP_LEVEL_FIELDS)}")

    declared = _validate_assets(data, errors)
    scene_masters, master_dependencies = _validate_scene_masters(data, declared, errors)
    used_globally: Dict[str, Set[str]] = {field: set() for field in ASSET_LABELS}
    for field in ASSET_LABELS:
        used_globally[field].update(master_dependencies[field])
    storyboards = data.get("storyboard")
    if not isinstance(storyboards, list):
        errors.append("顶层 storyboard 必须是数组")
        return errors
    if not storyboards:
        errors.append("顶层 storyboard 不得为空")
        return errors

    parsed_storyboards: List[List[str]] = []
    storyboard_profiles: List[List[ShotProfile]] = []
    seen_storyboard_names: Set[str] = set()
    logical_scene_storyboards: Dict[str, Set[int]] = {}
    storyboard_scene_tokens: List[Set[str]] = []
    for index, shot in enumerate(storyboards):
        location = f"storyboard[{index}]"
        if not isinstance(shot, dict):
            errors.append(f"{location} 必须是对象")
            parsed_storyboards.append([])
            storyboard_profiles.append([])
            storyboard_scene_tokens.append(set())
            continue
        if list(shot.keys()) != STORYBOARD_FIELDS:
            errors.append(f"{location} 分镜字段顺序必须为 {', '.join(STORYBOARD_FIELDS)}")

        name = shot.get("name")
        if not isinstance(name, str) or not name:
            errors.append(f"{location}.name 必须是非空字符串")
        elif len(name) > 15:
            errors.append(f"{location}.name 不得超过 15 字")
        elif name in seen_storyboard_names:
            errors.append(f"{location}.name 分镜名称重复: {name}")
        else:
            seen_storyboard_names.add(name)

        duration = shot.get("duration")
        if not _is_int(duration):
            errors.append(f"{location}.duration 必须是整数")
        elif not 4 <= duration <= duration_sec:
            position = "非末镜" if index < len(storyboards) - 1 else "末镜"
            errors.append(f"{location} {position} duration 必须在 4..{duration_sec} 范围内")

        prompt = shot.get("prompt")
        if not isinstance(prompt, str):
            errors.append(f"{location}.prompt 必须是字符串")
            shot_lines: List[str] = []
            profiles: List[ShotProfile] = []
        else:
            _validate_no_internal_syntax(prompt, index, errors)
            shot_lines = _parse_shot_lines(prompt, index, errors)
            profiles = _validate_model_shots(shot_lines, index, errors)
            if _is_int(duration):
                _validate_visual_beat_density(index, duration, len(shot_lines), errors)
            if shot_lines and "不出现任何文字字幕" not in shot_lines[-1]:
                errors.append(f"{location} 最后一个子镜头必须包含“不出现任何文字字幕”")
        parsed_storyboards.append(shot_lines)
        storyboard_profiles.append(profiles)

        reference_sets: Dict[str, Optional[Set[str]]] = {}
        for field in ASSET_LABELS:
            reference_sets[field] = _validate_reference_array(
                shot, field, index, declared, errors
            )

        tokens_by_field: Dict[str, Set[str]] = {field: set() for field in ASSET_LABELS}
        if isinstance(prompt, str):
            for token_type, token_name in TOKEN_RE.findall(prompt):
                field = TOKEN_TO_FIELD[token_type]
                tokens_by_field[field].add(token_name)

        for field, label in ASSET_LABELS.items():
            token_names = tokens_by_field[field]
            references = reference_sets[field]
            used_globally[field].update(token_names)
            for token_name in token_names:
                if token_name not in declared[field]:
                    errors.append(f"{location} {label}引用“{token_name}”未在顶层资产中声明")
            if references is not None and references != token_names:
                missing = sorted(token_names - references)
                extra = sorted(references - token_names)
                details = []
                if missing:
                    details.append(f"数组缺少 {missing}")
                if extra:
                    details.append(f"数组多出 {extra}")
                errors.append(
                    f"{location}.{field} 引用数组与 prompt token 不闭环: " + "；".join(details)
                )

        scene_tokens = tokens_by_field["scene"]
        storyboard_scene_tokens.append(scene_tokens)
        for scene_name in scene_tokens:
            logical_name = (
                scene_name[len(SPACE_MASTER_PREFIX) :]
                if scene_name.startswith(SPACE_MASTER_PREFIX)
                else scene_name
            )
            logical_scene_storyboards.setdefault(logical_name, set()).add(index)
        for base, master in scene_masters.items():
            if base in scene_tokens and master in scene_tokens:
                errors.append(
                    f"{location} 已引用空间母版“{master}”，不得同时发送基础空景“{base}”"
                )

    _validate_native_fast_recap_density(storyboards, errors)
    _validate_storyboard_bridges(parsed_storyboards, errors)
    errors.extend(validate_directing_arc(storyboard_profiles))
    for base, indexes in logical_scene_storyboards.items():
        if len(indexes) < 2:
            continue
        master = scene_masters.get(base)
        if master is None:
            errors.append(
                f"基础场景“{base}”跨 {len(indexes)} 个 storyboard，必须声明“{SPACE_MASTER_PREFIX}{base}”"
            )
            continue
        for index in sorted(indexes):
            if master not in storyboard_scene_tokens[index]:
                errors.append(
                    f"storyboard[{index}] 属于跨片段场景“{base}”，必须只引用空间母版“{master}”"
                )
    for field, label in ASSET_LABELS.items():
        for unused in sorted(declared[field] - used_globally[field]):
            errors.append(f"顶层{label}资产“{unused}”未被任何分镜引用")
    if narration_plan is not None:
        ledger = _validate_voice_ledger(data, narration_plan, source_text, errors)
        if ledger is None:
            _validate_prompt_content_durations(
                storyboards,
                parsed_storyboards,
                duration_sec,
                errors,
            )
        else:
            mapped_units, mapped_unit_shots = ledger
            _validate_content_durations(
                storyboards,
                parsed_storyboards,
                mapped_units,
                duration_sec,
                errors,
            )
            _validate_storyboard_packing(
                storyboards,
                mapped_units,
                duration_sec,
                errors,
            )
            _validate_plan_scene_alignment(
                mapped_unit_shots,
                parsed_storyboards,
                errors,
            )
    return errors


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("json_file", type=Path, help="待校验的 UTF-8 JSON 文件")
    parser.add_argument(
        "--duration-sec",
        type=int,
        required=True,
        help="分镜主切割时长上限（秒；每个分镜为 4..该值）",
    )
    parser.add_argument(
        "--narration-plan",
        type=Path,
        required=True,
        help="已通过校验的 narration_plan.json，用于语音正反向对账",
    )
    parser.add_argument(
        "--source",
        type=Path,
        help="可选的机器原文锚点 source.txt；项目 Skill Run 存在时必须传入",
    )
    return parser


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = build_parser().parse_args(argv)
    data, load_errors = load_json(args.json_file)
    narration_plan = None
    source_text: Optional[str] = None
    if args.narration_plan is not None:
        narration_plan, plan_load_errors = load_json(args.narration_plan)
        load_errors.extend(f"narration_plan: {error}" for error in plan_load_errors)
    source_path = args.source
    if source_path is None and args.narration_plan is not None:
        implicit_source = args.narration_plan.parent / "source.txt"
        if implicit_source.is_file():
            source_path = implicit_source
    if source_path is not None:
        try:
            source_text = source_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            load_errors.append(f"无法读取原文文件 {source_path}: {exc}")
    if load_errors:
        for error in load_errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 2
    errors = validate_storyboard(data, args.duration_sec, narration_plan, source_text)
    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1
    print("OK: storyboard JSON is valid")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
